class TreeNode:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build_tree(arr):
    if not arr or arr[0] is None:
        return None
    root = TreeNode(arr[0])
    queue = [root]
    i = 1
    while i < len(arr) and queue:
        node = queue.pop(0)
        if i < len(arr):
            left_val = arr[i]
            i += 1
            if left_val is not None:
                node.left = TreeNode(left_val)
                queue.append(node.left)
        if i < len(arr):
            right_val = arr[i]
            i += 1
            if right_val is not None:
                node.right = TreeNode(right_val)
                queue.append(node.right)
    return root


def width_of_binary_tree(root_arr):
    root = build_tree(root_arr)
    if root is None:
        return 0

    max_width = 0
    queue = [(root, 0)]
    while queue:
        level_size = len(queue)
        _, first_index = queue[0]
        last_index = first_index
        for _ in range(level_size):
            node, index = queue.pop(0)
            last_index = index
            rebased = index - first_index
            if node.left:
                queue.append((node.left, 2 * rebased + 1))
            if node.right:
                queue.append((node.right, 2 * rebased + 2))
        max_width = max(max_width, last_index - first_index + 1)
    return max_width

